import{_ as i,o as a,c as e,ai as l}from"./chunks/framework.Duywnu3E.js";const c=JSON.parse('{"title":"5. Настройте безопасный удалённый доступ на серверах HQ-SRV и BR-SRV:","description":"","frontmatter":{},"headers":[],"relativePath":"module1/task1-5.md","filePath":"module1/task1-5.md"}'),n={name:"module1/task1-5.md"};function t(h,s,p,r,d,k){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="_5-настроите-безопасныи-удаленныи-доступ-на-серверах-hq-srv-и-br-srv" tabindex="-1">5. Настройте безопасный удалённый доступ на серверах HQ-SRV и BR-SRV: <a class="header-anchor" href="#_5-настроите-безопасныи-удаленныи-доступ-на-серверах-hq-srv-и-br-srv" aria-label="Permalink to “5. Настройте безопасный удалённый доступ на серверах HQ-SRV и BR-SRV:”">​</a></h1><details class="details custom-block"><summary>Details</summary><ul><li><p>Для подключения используйте порт 2026</p></li><li><p>Разрешите подключения исключительно пользователю sshuser</p></li><li><p>Ограничьте количество попыток входа до двух</p></li><li><p>Настройте баннер «Authorized access only»</p></li></ul></details><p>Устанавливаем SSH-сервер, если он ещё не установлен.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssh-server</span></span></code></pre></div><p>Все дальнейшие изменения производятся в конфигурационном файле <code>/etc/openssh/sshd_config</code> на хостах <code>HQ-SRV</code> и <code>BR-SRV</code>.</p><h2 id="_5-1-настроика-порта-подключения" tabindex="-1">5.1 Настройка порта подключения <a class="header-anchor" href="#_5-1-настроика-порта-подключения" aria-label="Permalink to “5.1 Настройка порта подключения”">​</a></h2><p>Находим строчку <code>#Port 22</code>, раскомментируем и изменяем значение на <code>2026</code>.</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark has-diff" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line diff remove"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span></span>
<span class="line diff add"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_5-2-разрешение-подключении-только-для-sshuser" tabindex="-1">5.2 Разрешение подключений только для sshuser <a class="header-anchor" href="#_5-2-разрешение-подключении-только-для-sshuser" aria-label="Permalink to “5.2 Разрешение подключений только для sshuser”">​</a></h2><p>Добавляем директиву <code>AllowUsers</code> в конец файла <code>/etc/openssh/sshd_config</code>.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-SRV / BR-SRV</span></span>
<span class="line"><span># /etc/openssh/sshd_config (в конец файла)</span></span>
<span class="line"><span>AllowUsers sshuser</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Директива <code>AllowUsers</code> задаёт белый список пользователей, которым разрешено подключение по SSH. Все остальные пользователи будут автоматически отклонены.</p></div><h2 id="_5-3-ограничение-количества-попыток-входа" tabindex="-1">5.3 Ограничение количества попыток входа <a class="header-anchor" href="#_5-3-ограничение-количества-попыток-входа" aria-label="Permalink to “5.3 Ограничение количества попыток входа”">​</a></h2><p>Находим строчку <code>#MaxAuthTries 6</code>, раскомментируем и изменяем значение на <code>2</code>.</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark has-diff" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line diff remove"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MaxAuthTries </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span></span>
<span class="line diff add"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MaxAuthTries </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_5-4-настроика-баннера-«authorized-access-only»" tabindex="-1">5.4 Настройка баннера «Authorized access only» <a class="header-anchor" href="#_5-4-настроика-баннера-«authorized-access-only»" aria-label="Permalink to “5.4 Настройка баннера «Authorized access only»”">​</a></h2><p>Находим строчку <code>#Banner none</code>, раскомментируем и указываем путь к файлу с текстом баннера.</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark has-diff" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#Banner none </span></span>
<span class="line diff remove add"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Banner </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">openssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">banner </span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Создаём файл баннера с необходимым содержимым.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorized access only&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/openssh/banner</span></span></code></pre></div><h2 id="_5-5-применение-и-проверка" tabindex="-1">5.5 Применение и проверка <a class="header-anchor" href="#_5-5-применение-и-проверка" aria-label="Permalink to “5.5 Применение и проверка”">​</a></h2><p>Перезапускаем сервис SSH для применения изменений.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span></span></code></pre></div><p>Для проверки пробуем подключиться с HQ-RTR к HQ-SRV по SSH.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HQ-RTR</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2026</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshuser@192.168.100.2</span></span></code></pre></div><p>Если подключение прошло успешно и вы видите баннер «Authorized access only» — конфигурация выполнена верно.</p><p><strong>Повторите те же действия на машине BR-SRV по аналогии.</strong></p><p>Полезные материалы:</p><ul><li><a href="https://www.altlinux.org/SSH" target="_blank" rel="noreferrer">https://www.altlinux.org/SSH</a></li></ul>`,29)])])}const g=i(n,[["render",t]]);export{c as __pageData,g as default};
